package catalog

import (
  "context"
  "time"
)

type Service struct {
  cache Cache
  store *Store
}

func (s *Service) Product(ctx context.Context, id string) (*Product, error) {
  key := "product:" + id
  if p, ok := s.cache.Get(key); ok {
    return p, nil
  }
  p, err := s.store.Find(ctx, id)
  if err != nil {
    return nil, err
  }
  s.cache.Set(key, p, 5*time.Minute)
  return p, nil
}

