type Service struct {
  cache Cache
  store *Store
  group singleflight.Group
}

func (s *Service) Product(ctx context.Context, id string) (*Product, error) {
  key := "product:" + id
  if p, ok := s.cache.Get(key); ok {
    return p, nil
  }
  v, err, _ := s.group.Do(key, func() (any, error) {
    p, err := s.store.Find(ctx, id)
    if err != nil {
      return nil, err
    }
    s.cache.Set(key, p, 5*time.Minute)
    return p, nil
  })
  if err != nil {
    return nil, err
  }
  return v.(*Product), nil
}

func (s *Service) Product(ctx context.Context, id string) (*Product, error) {
  key := "product:" + id
  if p, ok := s.cache.Get(key); ok {
    return p, nil
  }
  ch := s.group.DoChan(key, func() (any, error) {
    ctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 3*time.Second)
    defer cancel()
    p, err := s.store.Find(ctx, id)
    if err != nil {
      return nil, err
    }
    s.cache.Set(key, p, 5*time.Minute)
    return p, nil
  })
  select {
  case <-ctx.Done():
    return nil, ctx.Err()
  case res := <-ch:
    if res.Err != nil {
      return nil, res.Err
    }
    return res.Val.(*Product), nil
  }
}
